-- 1.000 sessões vinculadas aos novos filmes. Uma sala por filme.
WITH
  novos_filmes AS (
    SELECT f.id_filme, f.duracao, ROW_NUMBER() OVER (ORDER BY f.id_filme) AS posicao
    FROM filmes f
    WHERE f.imagem LIKE 'https://images.metahub.space/poster/%'
      AND EXISTS (SELECT 1 FROM filmes_imagens i WHERE i.id_filme=f.id_filme AND i.tipo='BANNER' AND i.principal)
  ),
  novas_salas AS (
    SELECT s.id_sala, s.capacidade, ROW_NUMBER() OVER (ORDER BY s.id_sala) AS posicao
    FROM salas s JOIN locais l ON l.id_local=s.id_local
    WHERE s.id_sala>=20000000 AND s.status='ATIVA' AND l.status='ATIVO'
  ),
  inicio_programacao AS (
    SELECT DATE_ADD(GREATEST(CURRENT_DATE, COALESCE(MAX(data), CURRENT_DATE)), INTERVAL 1 DAY) AS dia FROM sessoes
  ),
  custos AS (
    SELECT f.id_filme, f.posicao, s.id_sala, a.dia, f.duracao+20 AS minutos,
           ROUND((ROUND(16000 * (f.duracao+20) / 1440,0)+18000)/LEAST(p.ocupacao_referencia,s.capacidade),0) AS centavos,
           p.markup_bps
    FROM novos_filmes f JOIN novas_salas s USING(posicao)
    CROSS JOIN inicio_programacao a JOIN precificacao_parametros p ON p.categoria='SESSION'
    WHERE f.posicao<=1000
  )
SELECT 40000000+posicao, id_filme, id_sala, dia, '10:00:00', SEC_TO_TIME(36000+minutos*60), 'ORIGINAL',
       (centavos+ROUND(centavos*markup_bps/10000,0))/100, 'AGENDADA', 160.00, 180.00
FROM custos
ORDER BY posicao;

COMMIT;
SELECT sessoes AS sessoes_novos_filmes FROM seed_operacao_1000_verificacao;
DROP TEMPORARY TABLE seed_operacao_1000_verificacao;
